const express = require('express');
const router = express.Router();
const db = require('../database');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// 角色常量定义
const ROLES = {
  USER: 'user',           // 普通用户
  ADMIN: 'admin',         // 管理员
  SUPER_ADMIN: 'super_admin', // 超级管理员
  INTERNAL: 'internal',    // 公司内部人员（发起维修/回收订单免付款，仅需申请）
  REPAIR: 'repair'        // 维修人员（负责处理维修/回收工单）
};

// 权限等级映射（数值越大权限越高）
const ROLE_LEVELS = {
  [ROLES.USER]: 1,
  [ROLES.INTERNAL]: 1,    // 内部人员视为普通用户等级（仅免付款下单，无管理权限）
  [ROLES.REPAIR]: 2,      // 维修人员可处理工单，等同管理员业务等级
  [ROLES.ADMIN]: 2,
  [ROLES.SUPER_ADMIN]: 3
};

/**
 * 生成JWT Token
 */
const generateToken = (user) => {
  return jwt.sign(
    {
      userId: user.id,
      openid: user.openid,
      role: user.role || ROLES.USER,
      nickname: user.nickname
    },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_EXPIRES_IN || '7d' }
  );
};

/**
 * JWT验证中间件 - 通用认证
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: '需要提供访问令牌' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: '无效或过期的令牌' });
    }
    req.user = user;
    next();
  });
};

/**
 * 角色验证中间件 - 检查用户是否具有指定角色
 */
const authorizeRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: '未认证用户' });
    }

    const userRole = req.user.role || ROLES.USER;
    const userLevel = ROLE_LEVELS[userRole] || 0;

    // 检查用户角色是否在允许的角色列表中，或权限等级是否足够
    const hasAccess = allowedRoles.some(role => {
      const allowedLevel = ROLE_LEVELS[role] || 0;
      return userLevel >= allowedLevel;
    });

    if (!hasAccess) {
      return res.status(403).json({ 
        error: '权限不足', 
        required: allowedRoles, 
        userRole: userRole 
      });
    }

    next();
  };
};

/**
 * 仅限超级管理员访问
 */
const superAdminOnly = (req, res, next) => {
  if (!req.user || req.user.role !== ROLES.SUPER_ADMIN) {
    return res.status(403).json({ error: '需要超级管理员权限' });
  }
  next();
};

module.exports = {
  ROLES,
  authenticateToken,
  authorizeRole,
  superAdminOnly,
  generateToken
};

// ================== backend/middleware/auth.js ==================
const jwt = require('jsonwebtoken');
const db = require('../database');

/**
 * 角色常量
 */
const ROLES = {
  USER: 'user',
  ADMIN: 'admin',
  SUPER_ADMIN: 'super_admin',
  INTERNAL: 'internal', // 公司内部人员（发起维修/回收订单免付款，仅需申请）
  REPAIR: 'repair'     // 维修人员（负责处理维修/回收工单）
};

/**
 * JWT验证中间件
 * 验证Token是否有效，并将用户信息解析到 req.user
 */
const authenticateToken = async (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; 
// 格式: Bearer TOKEN

    if (!token) {
      return res.status(401).json({
        success: false,
        error: '需要提供访问令牌'
      });
    }

    const decoded = jwt.verify(token, process.env.JWT_SECRET || '****...****');

    // 从数据库获取最新用户信息
    const users = await db.query(
      'SELECT id, openid, nickname, real_name, phone, email, avatar_url, role, status FROM users WHERE id = 
?',
      [decoded.userId]
    );

    if (users.length === 0) {
      return res.status(401).json({
        success: false,
        error: '用户不存在'
      });
    }

    const user = users[0];

    if (user.status !== 1) {
      return res.status(403).json({
        success: false,
        error: '用户已被禁用'
      });
    }

    req.user = user;
    req.token = token;
    next();
  } catch (error) {
    console.error('Token验证错误:', error);
    return res.status(401).json({
      success: false,
      error: '无效或过期的令牌'
    });
  }
};

/**
 * 生成JWT Token
 */
const generateToken = (user) => {
  const payload = {
    userId: user.id,
    openid: user.openid,
    nickname: user.nickname,
    role: user.role
  };

  const options = {
    expiresIn: process.env.JWT_EXPIRES_IN || '7d'
  };

  return jwt.sign(payload, process.env.JWT_SECRET || '****...****', options);
};

/**
 * 管理员权限验证中间件
 * 只有管理员角色才能访问
 */
const requireAdmin = (req, res, next) => {
  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: '需要先登录'
    });
  }

  if (req.user.role !== ROLES.ADMIN && req.user.role !== ROLES.SUPER_ADMIN) {
    return res.status(403).json({
      success: false,
      error: '需要管理员权限',
      currentRole: req.user.role
    });
  }

  next();
};

/**
 * 超级管理员权限验证中间件
 * 只有超级管理员角色才能访问
 */
const requireSuperAdmin = (req, res, next) => {
  if (!req.user) {
    return res.status(401).json({
      success: false,
      error: '需要先登录'
    });
  }

  if (req.user.role !== ROLES.SUPER_ADMIN) {
    return res.status(403).json({
      success: false,
      error: '需要超级管理员权限',
      currentRole: req.user.role
    });
  }

  next();
};

/**
 * 角色权限验证中间件
 * @param {string|Array} allowedRoles - 允许的角色或角色数组
 */
const authorizeRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        error: '需要先登录'
      });
    }

    const roles = Array.isArray(allowedRoles) ? allowedRoles : [allowedRoles];

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        error: '权限不足',
        currentRole: req.user.role,
        allowedRoles: roles
      });
    }

    next();
  };
};

module.exports = {
  ROLES,
  authenticateToken,
  generateToken,
  requireAdmin,
  requireSuperAdmin,
  authorizeRole
};

// ================== backend/middleware/imageCompress.js ==================
const sharp = require('sharp');
const path = require('path');
const fs = require('fs');

/**
 * 压缩图片中间件
 * @param {Object} file - 上传的文件对象
 * @param {Object} options - 压缩选项
 * @returns {Promise<Object>} 压缩后的文件信息
 */
async function compressImage(file, options = {}) {
  const {
    maxWidth = 200,
    maxHeight = 200,
    quality = 80,
    format = 'jpeg',
    fit = 'cover'
  } = options;

  try {
    const inputPath = file.path;
    const filename = file.filename;
    const uploadDir = path.dirname(inputPath);

    // 生成压缩后的文件名
    const compressedFilename = `compressed-${filename.replace(/\.[^.]+$/, '')}.${format}`;
    const compressedPath = path.join(uploadDir, compressedFilename);

    // 使用sharp进行压缩
    let transform = sharp(inputPath)
      .resize(maxWidth, maxHeight, {
        fit,
        position: 'center'
      });

    // 根据格式设置质量
    if (format === 'jpeg') {
      transform = transform.jpeg({ quality });
    } else if (format === 'png') {
      transform = transform.png({ quality });
    } else if (format === 'webp') {
      transform = transform.webp({ quality });
    }

    // 保存压缩后的图片
    await transform.toFile(compressedPath);

    // 获取文件大小
    const originalStats = fs.statSync(inputPath);
    const compressedStats = fs.statSync(compressedPath);

    console.log(`图片压缩完成:`, {
      original: `${(originalStats.size / 1024).toFixed(2)} KB`,
      compressed: `${(compressedStats.size / 1024).toFixed(2)} KB`,
      ratio: `${((1 - compressedStats.size / originalStats
.size) * 100).toFixed(2)}% 压缩率`
    });

    // 删除原始文件
    fs.unlinkSync(inputPath);

    return {
      ...file,
      filename: compressedFilename,
      path: compressedPath,
      size: compressedStats.size
    };
  } catch (error) {
    console.error('图片压缩失败:', error);
    throw error;
  }
}

/**
 * Multer存储引擎，包含自动压缩
 */
const createCompressedStorage = (uploadDir) => {
  return {
    destination: (req, file, cb) => {
      cb(null, uploadDir);
    },
    filename: (req, file, cb) => {
      const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
      cb(null, req.user?.userId + '-' + uniqueSuffix + path.extname(file.originalname));
    }
  };
};

module.exports = {
  compressImage,
  createCompressedStorage
};

