async function ensureUnreadColumns() {
  const specs = [
    { name: 'user_unread', def: "ADD COLUMN user_unread TI
NYINT(1) NULL DEFAULT 0 COMMENT '用户未读标记: 1-有更新未查看'" },
    { name: 'admin_unread', def: "ADD COLUMN admin_unread 
TINYINT(1) NULL DEFAULT 0 COMMENT '管理员未读标记: 1-有更新未查看'" },
    { name: 'reject_reason', def: "ADD COLUMN reject_reaso
n VARCHAR(255) NULL COMMENT '驳回/取消原因'" }
  ];
  for (const s of specs) {
    try {
      const exists = await hasOrderColumn(s.name);
      if (exists) continue;
      await db.query(`ALTER TABLE orders ${s.def}`);
    } catch (e) {
      const dup = e && (e.code === 'ER_DUP_FIELDNAME' || e.errno === 1060 || String(e.message || '').include
s('Duplicate column'));
      if (!dup) throw e;
    }
  }
}

async function trySetUnread(orderId, { user, admin } = {}) {
  await ensureUnreadColumns();
  const sets = [];
  const params = [];
  if (user !== undefined) { sets.push('user_unread = ?'); params.push(user ? 1 : 0); }
  if (admin !== undefined) { sets.push('admin_unread = ?'); params.push(admin ? 1 : 0); }
  if (sets.length === 0) return;
  params.push(orderId);
  const sql = `UPDATE orders SET ${sets.join(', ')}, updated_at = NOW() WHERE id = ?`;
  try {
    await db.query(sql, params);
  } catch (e) {
    const missing = e && (e.code === 'ER_BAD_FIELD_ERROR' || e.errno === 1054 || String(e.message || '').inc
ludes('Unknown column'));
    if (!missing) throw e;
    await ensureUnreadColumns();
    await db.query(sql, params);
  }
}

