  const files = exists ? fs.readdirSync(dir).filter(f => f.includes('test_upload') || f.endsWith('.png')) : 
[];
  console.log(`[共享目录核对] /uploads 存在=${exists}, 上传后文件数=${fs
.readdirSync(dir).length}`);
  fs.unlinkSync(tmp);

  process.exit(0);
}
main().catch(e => { console.error('异常:', e.message); proce
ss.exit(1); });

